/**
 * value.js 4.2.0 — `simulateColorVision` against independent implementations
 * (SPEC §7 A–E, COHESION §0hf.3).
 *
 * The reference vectors are `test/fixtures/cvd/reference.json`, generated by
 * `test/support/cvd_reference.py` from colorspacious 1.1.2 and DaltonLens 0.1.5
 * (versions and command in the fixture's header). Tolerances, stated:
 *   - Machado table: 0 against colorspacious, 1e-12 against DaltonLens;
 *   - matrix application, pre-clip: 1e-12 on the tenths, 1e-9 off them;
 *   - post-clip linear: 1e-6;
 *   - Viénot constants: 1e-12 against DaltonLens and against a re-derivation;
 *   - end to end through `toRgba8`: ±1 byte (DaltonLens computes in float32 and
 *     truncates to uint8).
 *
 * §0hf.3 property 2 ("severity 1 equals the dichromat form") is enforced per
 * model, as the judged spec restates it (SPEC §0): Machado s = 1 is its own
 * published 1.0 row, Viénot is a projection, and the cross-model distance is a
 * committed regression bound.
 */
import { describe, expect, it } from "vitest";

import reference from "./fixtures/cvd/reference.json";
import {
    convertColor,
    deltaEOK,
    linearSrgb,
    mapColorToGamut,
    oklch,
    rgb,
    simulateColorVision,
    toRgba8,
    type AnyColor,
    type ColorVisionKind,
} from "../src/color/index";
import {
    MACHADO_2009,
    VIENOT_1999,
    colorVisionMatrix,
    simulateLinearUnclipped,
    type Matrix,
} from "../src/color/vision";

const KINDS: readonly ColorVisionKind[] = ["protan", "deutan", "tritan"];

const unwrap = <T>(result: { ok: true; value: T } | { ok: false; error: unknown }): T => {
    if (!result.ok) throw new Error(JSON.stringify(result.error));
    return result.value;
};
const hex = (h: string): AnyColor => {
    const n = Number.parseInt(h.slice(1), 16);
    return unwrap(rgb((n >> 16) & 255, (n >> 8) & 255, n & 255));
};
const flat = (m: readonly (readonly number[])[]) => m.flat();
const maxAbs = (a: readonly number[], b: readonly number[]) =>
    Math.max(...a.map((x, i) => Math.abs(x - b[i]!)));
const channels = (color: AnyColor) => color.channels as readonly number[];

/** mulberry32 — a seeded PRNG so the sampled properties are reproducible. */
function seeded(seed: number) {
    let a = seed >>> 0;
    return () => {
        a = (a + 0x6d2b79f5) >>> 0;
        let t = a;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}

/** A 9³ sRGB cube plus seeded OKLCh samples mapped into sRGB. */
function samples(): AnyColor[] {
    const out: AnyColor[] = [];
    for (let r = 0; r < 9; r++) for (let g = 0; g < 9; g++) for (let b = 0; b < 9; b++) {
        out.push(unwrap(rgb(r * 255 / 8, g * 255 / 8, b * 255 / 8)));
    }
    const random = seeded(0x4_2_0);
    for (let i = 0; i < 400; i++) {
        const raw = unwrap(oklch(random(), random() * 0.4, random() * 360));
        out.push(unwrap(mapColorToGamut(raw, "srgb")));
    }
    return out;
}

const apply = (m: Matrix, [r, g, b]: readonly number[]) => [
    m[0] * r! + m[1] * g! + m[2] * b!,
    m[3] * r! + m[4] * g! + m[5] * b!,
    m[6] * r! + m[7] * g! + m[8] * b!,
];
const clip = (values: readonly number[]) => values.map((v) => Math.min(1, Math.max(0, v)));

describe("A. Machado 2009 table fidelity", () => {
    it("all 33 matrices equal colorspacious MACHADO_ET_AL_MATRICES with tolerance 0", () => {
        for (const kind of KINDS) {
            const shipped = MACHADO_2009[kind];
            expect(shipped).toHaveLength(11);
            reference.machado.colorspacious[kind].forEach((matrix, i) => {
                // `===`, not Object.is: the published severity-0 row spells some zeros as -0.
                flat(matrix).forEach((value, k) => expect(shipped[i]![k] === value, `${kind} ${i / 10} [${k}]`).toBe(true));
            });
        }
    });

    it("all 33 matrices equal DaltonLens machado_2009_matrices to 1e-12 (a second transcription)", () => {
        for (const kind of KINDS) {
            reference.machado.daltonlens[kind].forEach((matrix, i) => {
                expect(maxAbs(MACHADO_2009[kind][i]!, flat(matrix))).toBeLessThanOrEqual(1e-12);
            });
        }
    });

    it("severity 0 is the exact identity and severity 1 the published 1.0 row, bit for bit", () => {
        for (const kind of KINDS) {
            expect(unwrap(colorVisionMatrix({ kind, severity: 0 }))).toEqual([1, 0, 0, 0, 1, 0, 0, 0, 1]);
            expect(unwrap(colorVisionMatrix({ kind, severity: 1 }))).toEqual(MACHADO_2009[kind][10]);
            expect(unwrap(colorVisionMatrix({ kind }))).toEqual(MACHADO_2009[kind][10]);
        }
    });

    it("the off-grid rule is colorspacious's (DaltonLens 0.1.5 does not scale its alpha by 10)", () => {
        const { offGrid } = reference;
        const ours = unwrap(colorVisionMatrix({ kind: "deutan", severity: 0.55 }));
        expect(maxAbs(ours, flat(offGrid.colorspacious))).toBeLessThanOrEqual(1e-12);
        // SPEC §7 B seed: the interpolated deutan s = 0.55 matrix, printed at 6 decimals (its
        // exact entries end in 5 at the 7th, so the printed seed sits a half step off: 1e-6).
        expect(maxAbs(ours, [0.523179, 0.641253, -0.164432, 0.193446, 0.768307, 0.038248, -0.010771, 0.029122, 0.981649]))
            .toBeLessThanOrEqual(1e-6);
        // DaltonLens's `alpha = severity - lower/10` lands near the 0.5 row, not halfway to 0.6.
        expect(offGrid.daltonlensAlpha).toBeCloseTo(0.05, 12);
        expect(maxAbs(ours, flat(offGrid.daltonlens))).toBeGreaterThan(1e-3);
    });
});

describe("B. matrix application against colorspacious, pre-clip", () => {
    it("every grid row (14 inputs × 3 kinds × 10 severities) to 1e-12 on the tenths and 1e-9 off them", () => {
        expect(reference.grid).toHaveLength(420);
        for (const row of reference.grid) {
            const ours = unwrap(simulateLinearUnclipped(hex(row.hex), { kind: row.kind as ColorVisionKind, severity: row.severity }));
            const onGrid = Number.isInteger(row.severity * 10);
            expect(maxAbs(ours, row.linear), `${row.kind} ${row.severity} ${row.hex}`).toBeLessThanOrEqual(onGrid ? 1e-12 : 1e-9);
        }
    });

    it("reproduces the SPEC seed vectors", () => {
        const seeds: [ColorVisionKind, number, string, number[]][] = [
            ["protan", 1, "#982a6b", [0.04206574280415923, 0.068745158832376, 0.15233943874858644]],
            ["deutan", 1, "#338c00", [0.2378650884666536, 0.18563597798438458, 0.010869744893457295]],
            ["tritan", 1, "#982a6b", [0.36615923594921057, 0.0186327112039554, 0.06217516818348805]],
            ["deutan", 0.55, "#1a5fa0", [0.02098334062072909, 0.10336499963915147, 0.3483029543646553]],
            ["protan", 0.05, "#a88f42", [0.3873721004393177, 0.27468104701404633, 0.05382277968922447]],
            ["tritan", 0.93, "#008e84", [-0.06713320805100162, 0.28761067500499243, 0.25554860406878593]],
        ];
        for (const [kind, severity, h, expected] of seeds) {
            const ours = unwrap(simulateLinearUnclipped(hex(h), { kind, severity }));
            expect(maxAbs(ours, expected), `${kind} ${severity} ${h}`).toBeLessThanOrEqual(1e-9);
        }
    });

    it("clips after the matrix: #0000ff protan s = 1 → [0, 0.099216, 1] to 1e-6", () => {
        const pre = unwrap(simulateLinearUnclipped(hex("#0000ff"), { kind: "protan" }));
        expect(pre[0]).toBeCloseTo(-0.204868, 6);
        const out = unwrap(simulateColorVision(hex("#0000ff"), { kind: "protan" }));
        expect(out.space).toBe("srgb-linear");
        expect(maxAbs(channels(out), [0, 0.099216, 1])).toBeLessThanOrEqual(1e-6);
        for (const row of reference.grid) {
            const post = unwrap(simulateColorVision(hex(row.hex), { kind: row.kind as ColorVisionKind, severity: row.severity }));
            expect(maxAbs(channels(post), clip(row.linear))).toBeLessThanOrEqual(1e-6);
        }
    });
});

describe("C. Viénot, Brettel & Mollon 1999", () => {
    const inverse = (m: readonly number[]) => {
        const [a, b, c, d, e, f, g, h, i] = m as [number, number, number, number, number, number, number, number, number];
        const det = a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
        return [
            (e * i - f * h) / det, (c * h - b * i) / det, (b * f - c * e) / det,
            (f * g - d * i) / det, (a * i - c * g) / det, (c * d - a * f) / det,
            (d * h - e * g) / det, (b * g - a * h) / det, (a * e - b * d) / det,
        ];
    };
    const multiply = (x: readonly number[], y: readonly number[]) =>
        Array.from({ length: 9 }, (_, k) => {
            const r = Math.floor(k / 3);
            const c = k % 3;
            return x[3 * r]! * y[c]! + x[3 * r + 1]! * y[3 + c]! + x[3 * r + 2]! * y[6 + c]!;
        });

    it("the shipped constants equal DaltonLens Simulator_Vienot1999().cvd_linear_rgb to 1e-12", () => {
        for (const kind of ["protan", "deutan"] as const) {
            expect(maxAbs(VIENOT_1999[kind], flat(reference.vienot.daltonlens[kind]))).toBeLessThanOrEqual(1e-12);
        }
    });

    it("re-running the derivation (Smith-Pokorny 1975 LMS, BT.709 primaries, projection onto the black-white-blue-yellow plane) lands on them", () => {
        const lmsFromRgb = multiply(flat(reference.vienot.LMS_from_XYZ), flat(reference.vienot.XYZ_from_linearRGB));
        const rgbFromLms = inverse(lmsFromRgb);
        const blue = apply(lmsFromRgb as unknown as Matrix, [0, 0, 1]);
        const yellow = apply(lmsFromRgb as unknown as Matrix, [1, 1, 0]);
        const n = [
            yellow[1]! * blue[2]! - yellow[2]! * blue[1]!,
            yellow[2]! * blue[0]! - yellow[0]! * blue[2]!,
            yellow[0]! * blue[1]! - yellow[1]! * blue[0]!,
        ] as const;
        const projection = {
            protan: [0, -n[1] / n[0], -n[2] / n[0], 0, 1, 0, 0, 0, 1],
            deutan: [1, 0, 0, -n[0] / n[1], 0, -n[2] / n[1], 0, 0, 1],
        };
        for (const kind of ["protan", "deutan"] as const) {
            const derived = multiply(rgbFromLms, multiply(projection[kind], lmsFromRgb));
            expect(maxAbs(VIENOT_1999[kind], derived), kind).toBeLessThanOrEqual(1e-12);
        }
    });

    it("fixes black, white, blue and yellow; rows 0 and 1 agree; V·V = V", () => {
        for (const kind of ["protan", "deutan"] as const) {
            const v = VIENOT_1999[kind];
            for (const fixed of [[0, 0, 0], [1, 1, 1], [0, 0, 1], [1, 1, 0]]) {
                expect(maxAbs(apply(v, fixed), fixed), `${kind} ${fixed}`).toBeLessThanOrEqual(1e-12);
            }
            expect(maxAbs(v.slice(0, 3), v.slice(3, 6))).toBeLessThanOrEqual(1e-12);
            expect(maxAbs(multiply(v, v), v)).toBeLessThanOrEqual(1e-15);
        }
    });

    it("refuses tritan and any severity other than 1 (the paper defines neither)", () => {
        const color = hex("#982a6b");
        expect(simulateColorVision(color, { kind: "tritan", method: "vienot" } as never)).toEqual({ ok: false, error: { code: "color_invalid_input" } });
        expect(simulateColorVision(color, { kind: "protan", method: "vienot", severity: 0.5 } as never)).toEqual({ ok: false, error: { code: "color_invalid_input" } });
        expect(simulateColorVision(color, { kind: "deutan", method: "vienot", severity: 1 }).ok).toBe(true);
    });
});

describe("D. end to end against DaltonLens simulate_cvd (uint8, ±1 byte)", () => {
    it("matches every recorded case, including the SPEC four", () => {
        const spec = [
            ["machado", "protan", "#338c00", [144, 126, 0]],
            ["vienot", "protan", "#338c00", [133, 133, 0]],
            ["machado", "deutan", "#982a6b", [89, 93, 104]],
            ["vienot", "deutan", "#982a6b", [92, 92, 104]],
        ] as const;
        for (const [method, kind, h, bytes] of spec) {
            expect(reference.endToEnd).toContainEqual({ method, kind, hex: h, uint8: [...bytes] });
        }
        for (const row of reference.endToEnd) {
            const options = { kind: row.kind, method: row.method } as never;
            const out = unwrap(toRgba8(unwrap(simulateColorVision(hex(row.hex), options)), { gamut: "clip" }));
            for (let i = 0; i < 3; i++) {
                expect(Math.abs(out[i]! - row.uint8[i]!), `${row.method} ${row.kind} ${row.hex} [${i}]`).toBeLessThanOrEqual(1);
            }
            expect(out[3]).toBe(255);
        }
    });
});

describe("E. properties", () => {
    const pool = samples();

    it("severity 0 is the identity: bit-identical in srgb-linear before the clip, the clipped input after", () => {
        for (const color of pool) {
            const linear = channels(unwrap(convertColor(color, "srgb-linear")));
            for (const kind of KINDS) {
                expect(unwrap(simulateLinearUnclipped(color, { kind, severity: 0 }))).toEqual(linear);
                expect(channels(unwrap(simulateColorVision(color, { kind, severity: 0 })))).toEqual(clip(linear));
            }
        }
    });

    it("Machado s = 1 is bit-equal to T[10]·x, then the clip", () => {
        for (const color of pool) {
            const linear = channels(unwrap(convertColor(color, "srgb-linear")));
            for (const kind of KINDS) {
                const expected = clip(apply(MACHADO_2009[kind][10]!, linear));
                expect(channels(unwrap(simulateColorVision(color, { kind })))).toEqual(expected);
            }
        }
    });

    it("the interpolation is continuous at every tenth and linear between them", () => {
        for (const kind of KINDS) {
            for (let k = 1; k <= 9; k++) {
                const below = unwrap(colorVisionMatrix({ kind, severity: k / 10 - 1e-13 }));
                const above = unwrap(colorVisionMatrix({ kind, severity: k / 10 + 1e-13 }));
                expect(maxAbs(below, above), `${kind} ${k / 10}`).toBeLessThanOrEqual(1e-12);
                expect(maxAbs(below, MACHADO_2009[kind][k]!)).toBeLessThanOrEqual(1e-12);
            }
            for (let k = 0; k < 10; k++) {
                const middle = unwrap(colorVisionMatrix({ kind, severity: (k + 0.5) / 10 }));
                const mean = MACHADO_2009[kind][k]!.map((v, i) => (v + MACHADO_2009[kind][k + 1]![i]!) / 2);
                expect(maxAbs(middle, mean), `${kind} ${(k + 0.5) / 10}`).toBeLessThanOrEqual(1e-12);
            }
        }
    });

    it("achromatic inputs stay achromatic (Machado to 2e-6, the published row sums; Viénot to 1e-12)", () => {
        for (let v = 0; v <= 255; v += 5) {
            const grey = unwrap(rgb(v, v, v));
            for (const kind of KINDS) {
                for (const severity of [0.1, 0.35, 0.5, 0.8, 1]) {
                    const [r, g, b] = channels(unwrap(simulateColorVision(grey, { kind, severity })));
                    expect(Math.max(r!, g!, b!) - Math.min(r!, g!, b!), `${kind} ${severity} grey ${v}`).toBeLessThanOrEqual(2e-6);
                }
            }
            for (const kind of ["protan", "deutan"] as const) {
                const [r, g, b] = channels(unwrap(simulateColorVision(grey, { kind, method: "vienot" })));
                expect(Math.max(r!, g!, b!) - Math.min(r!, g!, b!)).toBeLessThanOrEqual(1e-12);
            }
        }
    });

    it("output lies in [0, 1]³ (out-of-gamut input is mapped first) and alpha passes through, \"none\" included", () => {
        const wide = [unwrap(oklch(0.7, 0.4, 150)), unwrap(oklch(0.5, 0.35, 300, 0.4)), unwrap(oklch(0.6, 0.2, 40, "none"))];
        for (const color of [...pool, ...wide]) {
            for (const kind of KINDS) {
                const out = unwrap(simulateColorVision(color, { kind, severity: 0.7 }));
                for (const c of channels(out)) expect(c >= 0 && c <= 1).toBe(true);
                expect(out.alpha).toBe(color.alpha);
            }
        }
    });

    it("errors: NaN severity, severity 1.01, an unknown kind, a missing channel", () => {
        const color = hex("#1a5fa0");
        expect(simulateColorVision(color, { kind: "protan", severity: Number.NaN })).toEqual({ ok: false, error: { code: "color_non_finite" } });
        expect(simulateColorVision(color, { kind: "protan", severity: 1.01 })).toEqual({ ok: false, error: { code: "color_out_of_range" } });
        expect(simulateColorVision(color, { kind: "protan", severity: -0.01 })).toEqual({ ok: false, error: { code: "color_out_of_range" } });
        expect(simulateColorVision(color, { kind: "achromat" } as never)).toEqual({ ok: false, error: { code: "color_invalid_input" } });
        expect(simulateColorVision(color, { kind: "protan", method: "brettel" } as never)).toEqual({ ok: false, error: { code: "color_invalid_input" } });
        expect(simulateColorVision(color, undefined as never)).toEqual({ ok: false, error: { code: "color_invalid_input" } });
        expect(simulateColorVision("#1a5fa0" as never, { kind: "protan" })).toEqual({ ok: false, error: { code: "color_invalid_input" } });
        expect(simulateColorVision(unwrap(linearSrgb(0.2, "none", 0.4)), { kind: "protan" })).toEqual({ ok: false, error: { code: "color_missing_channel" } });
    });

    it("§0hf.3 property 2, per model (SPEC §0 (c)): Machado s = 1 vs Viénot on a 33³ cube stays inside the committed bound", () => {
        for (const kind of ["protan", "deutan"] as const) {
            const distances: number[] = [];
            for (let r = 0; r < 33; r++) for (let g = 0; g < 33; g++) for (let b = 0; b < 33; b++) {
                const color = unwrap(rgb(r * 255 / 32, g * 255 / 32, b * 255 / 32));
                const machado = unwrap(simulateColorVision(color, { kind }));
                const vienot = unwrap(simulateColorVision(color, { kind, method: "vienot" }));
                distances.push(unwrap(deltaEOK(machado, vienot)));
            }
            distances.sort((x, y) => x - y);
            const at = (q: number) => distances[Math.min(distances.length - 1, Math.floor(q * distances.length))]!;
            expect(at(0.5), `${kind} median`).toBeLessThanOrEqual(0.03);
            expect(at(0.95), `${kind} p95`).toBeLessThanOrEqual(0.085);
            expect(distances.at(-1)!, `${kind} max`).toBeLessThanOrEqual(0.11);
        }
    }, 60_000);
});
